import { invoke } from "@tauri-apps/api/core";
import { useEffect, useState } from "react";

type Thumbnail = { name: string; url: string };

/** The last images generated by the local engine, shown from AiWin11's images folder. */
export function Gallery() {
  const [images, setImages] = useState<Thumbnail[]>();
  const [status, setStatus] = useState("");

  async function load() {
    try {
      const names = await invoke<string[]>("list_generated_images");
      const loaded: Thumbnail[] = [];
      for (const name of names) {
        const bytes = await invoke<ArrayBuffer>("read_generated_image", { name });
        loaded.push({ name, url: URL.createObjectURL(new Blob([bytes], { type: "image/png" })) });
      }
      setImages((previous) => {
        previous?.forEach((image) => URL.revokeObjectURL(image.url));
        return loaded;
      });
      setStatus("");
    } catch {
      setStatus("La galerie est indisponible.");
    }
  }

  useEffect(() => {
    void load();
  }, []);

  useEffect(() => () => images?.forEach((image) => URL.revokeObjectURL(image.url)), [images]);

  return (
    <div className="task-form">
      <div className="section-header">
        <h3>Images générées</h3>
        <button type="button" onClick={() => void load()}>
          Actualiser
        </button>
      </div>
      {images?.length === 0 && <p>Aucune image générée pour l’instant.</p>}
      {!!images?.length && (
        <ul className="gallery">
          {images.map((image) => (
            <li key={image.name}>
              <img src={image.url} alt={`Image générée ${image.name}`} loading="lazy" />
              <span>{image.name}</span>
            </li>
          ))}
        </ul>
      )}
      <p role="status">{status}</p>
    </div>
  );
}
